    private val outlines: Map<Int, Int> = fills.entries.associate { (outline, fill) -> fill to outline }

    /** Outline ids whose fill twin has the same path at the pinned commit, so filling them shows nothing. */
    private val sameWhenFilled: Set<Int> = setOf(
        home,
        setup,
        nextPage,
        previousPage,
        undo,
        redo,
        playPause,
        back,
        recents,
        lastApp,
        splitScreen,
        screenshot,
        search,
        close,
        expandMore,
        expandLess,
        more,
        add,
        refresh,
        wallpaper,
        open,
        chevron,
        code,
    )

    /** The filled twin of [id]; a filled id, or an id that isn't a symbol, comes back unchanged. */
    @DrawableRes
    fun filled(@DrawableRes id: Int): Int = fills[id] ?: id

    /** The outline twin of [id]; an outline id, or an id that isn't a symbol, comes back unchanged. */
    @DrawableRes
    fun outline(@DrawableRes id: Int): Int = outlines[id] ?: id

    /** [filled] when [selected], else the outline: the rail and pickers fill the chosen item's icon. */
    @DrawableRes
    fun filledIf(@DrawableRes id: Int, selected: Boolean): Int = if (selected) filled(id) else outline(id)

    /**
     * False for the symbols whose filled and outline drawings are identical (Home, Setup, chevrons, arrows,
     * Close, Add, …): their selected state needs something besides the fill.
     */
    fun fillLooksDifferent(@DrawableRes id: Int): Boolean = outline(id) in fills && outline(id) !in sameWhenFilled

    /** The outline symbol for a map.json slot name such as "open_camera", or null. */
    @DrawableRes
    fun forSlot(slot: String): Int? = slots[slot]

    /** The symbol for a pen action, as the action picker and binding chips show it. */
    @DrawableRes
    fun forIntent(intent: PenIntent): Int = when (intent) {
        PenIntent.SHUTTER -> shutter
        PenIntent.NEXT_PAGE -> nextPage
        PenIntent.PREVIOUS_PAGE -> previousPage
        PenIntent.UNDO -> undo
        PenIntent.REDO -> redo
        PenIntent.SCREENSHOT -> screenshot
        PenIntent.BACK -> back
        PenIntent.HOME -> homeAction
        PenIntent.RECENTS -> recents
        PenIntent.SPLIT_SCREEN -> splitScreen
        PenIntent.NOTIFICATIONS -> notifications
        PenIntent.OPEN_CAMERA -> openCamera
        PenIntent.OPEN_LIBRARY -> library
        PenIntent.OPEN_NOTES -> openNotes
        PenIntent.PLAY_PAUSE -> playPause
        PenIntent.NEXT_TRACK -> nextTrack
        PenIntent.PREVIOUS_TRACK -> previousTrack
        PenIntent.LAST_APP -> lastApp
        PenIntent.QUICK_SETTINGS -> quickSettings
        PenIntent.ASSISTANT -> assistant
        PenIntent.VOLUME_UP -> volumeUp
        PenIntent.VOLUME_DOWN -> volumeDown
        PenIntent.DO_NOT_DISTURB -> dnd
        PenIntent.FLASHLIGHT -> flashlight
        PenIntent.ROTATION_LOCK -> rotationLock
    }

    /**
     * The symbol for a pen control id ([PenControl.id]): the Focus Pen Pro gestures have their own; the
     * upper and lower barrel buttons get up and down chevrons; anything else gets the pen.
     */
    @DrawableRes
    fun forControl(controlId: String): Int = when (controlId) {
        PenControl.PINCH.id -> squeeze
        PenControl.SLIDE_UP.id -> slideUp
        PenControl.SLIDE_DOWN.id -> slideDown
        PenControl.DOUBLE_TAP.id -> doubleTap
        PenControl.UPPER.id -> expandLess
        PenControl.LOWER.id -> expandMore
        else -> pen
    }
